/* =========================
   QUESTION HELPERS
   ========================= */
function topic(d){return Object.assign({name:''},d)}
function q(id,sec,m,prompt,expected,criteria,fix){return {id,sec,m,type:'short',prompt,expected,criteria:(Array.isArray(criteria)?criteria:[]).map(c=>Array.isArray(c)?{concept:c.join(' / '),terms:c}:{concept:c,terms:[c]}),fix:fix||'Compare your answer with the expected answer and correct the missing concept.'}}
function short(id,sec,m,prompt,expected,terms,fix){return q(id,sec,m,prompt,expected,terms,fix)}
function mcq(id,sec,m,prompt,options,correct,explain){return {id,sec,m,type:'mcq',prompt,options,correct,expected:options[correct],explain}}
function numeric(id,sec,m,prompt,answer,explain){return {id,sec,m,type:'numeric',prompt,answer,expected:answer,explain,criteria:[{concept:'correct numerical result',terms:[answer]}],fix:'Recalculate carefully, showing substitution and the arithmetic step.'}}
function truefalse(id,sec,m,prompt,answer,explain){return {id,sec,m,type:'tf',prompt,answer,expected:answer?'True':'False',explain,criteria:[{concept:'correct judgement',terms:[answer?'true':'false']}],fix:'Decide whether the statement is true, then compare your reason with the explanation.'}}
function genQuestions(arr){return arr}
function normalizeText(s){return String(s||'').toLowerCase().replace(/[₂]/g,'2').replace(/[³]/g,'3').replace(/[₄-₉]/g,m=>String('₄₅₆₇₈₉'.indexOf(m)+4)).replace(/[^a-z0-9.+\-=/ ]/g,' ')}
function criterionHit(answer,terms){const t=normalizeText(answer);return terms.some(term=>{const n=normalizeText(term).trim();if(!n)return false;return t.includes(n)})}

