function pastPapersFor(name){const key=topicKey(name);for(const [k,v] of Object.entries(pastPaperBank))if(topicKey(k)===key)return v;const alias=topicAliases[key];if(alias){for(const [k,v] of Object.entries(pastPaperBank))if(topicKey(k)===topicKey(alias))return v}return []}
function cloneQuestion(q){return JSON.parse(JSON.stringify(q))}
function enrichSessionData(d){
 const papers=S.general?[]:pastPapersFor(S.topic||d.name);
 const base=Object.assign({},d,{questions:(d.questions||[]).map(cloneQuestion)});
 base.pastPapers=papers.map(cloneQuestion);
 const seen=new Set(base.questions.map(x=>x.id));
 for(const p of base.pastPapers)if(!seen.has(p.id)){base.questions.push(p);seen.add(p.id)}
 return base;
}
