function diagramTeachingNotes(type){
 const map={
  calculus:[['What to notice','The derivative controls the tangent gradient. Stationary points occur where the first derivative is zero.'],['Exam use','Move between the function, f′ and f′′: gradient, stationary points, concavity and inflection.'],['Common mistake','Using f′′ to find a tangent gradient, or giving only x-values when coordinates are required.']],
  force:[['What to notice','Every arrow represents a force acting on one chosen object. Direction and labels matter.'],['Exam use','Free-body diagrams are often the first step before writing ΣF=ma in a chosen direction.'],['Common mistake','Drawing motion arrows or forces exerted by the object instead of forces acting on it.']],
  circuit:[['What to notice','Series has one path; parallel has branches. Ammeter/voltmeter placement changes what is measured.'],['Exam use','Trace current paths first, then apply current/voltage rules and Ohm’s law.'],['Common mistake','Treating voltage as something that “flows” or placing a voltmeter in series.']],
  trig:[['What to notice','The chosen angle determines opposite and adjacent; the hypotenuse is always opposite the right angle.'],['Exam use','Mark the known sides/angles before selecting a ratio or theorem.'],['Common mistake','Naming opposite/adjacent before choosing the reference angle.']],
  graph:[['What to notice','Intercepts, turning points, domain/range and transformations carry meaning.'],['Exam use','Read features from the graph and connect them to algebraic conditions.'],['Common mistake','Sketching shape without correct intercepts/asymptotes or labelled scale where required.']],
  cell:[['What to notice','Structure is linked to function. Labels must point to the actual structure.'],['Exam use','Questions often ask identify → state function → explain adaptation.'],['Common mistake','Giving a generic function that does not match the labelled organelle.']],
  genetics:[['What to notice','Track alleles, genotype and phenotype separately.'],['Exam use','Set up parental genotypes, gametes, cross and probability in a clear sequence.'],['Common mistake','Confusing dominant phenotype with homozygous genotype.']],
  dna:[['What to notice','Base pairing and sequence determine the information carried.'],['Exam use','Follow replication/transcription/translation in the correct direction and sequence.'],['Common mistake','Mixing DNA bases with RNA bases or skipping the mRNA step.']],
  particles:[['What to notice','Composition and bonding distinguish element, compound and mixture.'],['Exam use','Use the particle arrangement as evidence for classification.'],['Common mistake','Calling any picture with more than one atom a mixture.']],
  reaction:[['What to notice','Atoms are rearranged; they are not created or destroyed.'],['Exam use','Count each element before and after balancing.'],['Common mistake','Changing subscripts instead of coefficients when balancing.']],
  probability:[['What to notice','Choose a representation that matches the event relationship.'],['Exam use','Use sample spaces, trees, Venn diagrams or tables to prevent double-counting.'],['Common mistake','Adding probabilities for events that overlap without subtracting the intersection.']],
  momentum:[['What to notice','Momentum is a vector, so direction/sign matters.'],['Exam use','Choose a positive direction before conservation calculations.'],['Common mistake','Adding magnitudes without signs in opposite-direction collisions.']],
  energy:[['What to notice','Track where energy starts, transfers and ends.'],['Exam use','Separate work-energy ideas from force equations and include units.'],['Common mistake','Using conservation of mechanical energy when non-conservative work is not accounted for.']],
  wave:[['What to notice','Amplitude and wavelength are different properties.'],['Exam use','Read the graph carefully before applying v=fλ.'],['Common mistake','Measuring wavelength from crest to trough instead of same-phase points.']],
  acidbase:[['What to notice','pH is logarithmic; strong/weak is not the same as concentrated/dilute.'],['Exam use','Identify acid/base species and use the correct concentration relationships.'],['Common mistake','Assuming every strong acid solution has the same pH.']]
 };
 const rows=map[type]||[['What to notice','Identify the information represented and the relationship between labelled features.'],['Exam use','Use the visual as evidence, not decoration.'],['Common mistake','Ignoring labels, scale, direction or units.']];
 return `<div class="diagramNotes">${rows.map(([a,b])=>`<div class="diagramNote"><b>${a}</b><p>${b}</p></div>`).join('')}</div>`;
}
