function diagramHTML(type){
 if(type==='particles')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Element vs compound vs mixture</div><div class="diagramhelp">Switch models, reveal labels and click a particle group.</div></div><div class="diagramcontrols"><button onclick="toggleLabels('particles')">Labels</button><button onclick="particleMode('element')">Element</button><button onclick="particleMode('compound')">Compound</button><button onclick="particleMode('mixture')">Mixture</button></div></div><div class="diagramcanvas" id="particlesCanvas">${particleSVG('compound')}</div><div class="diagramcaption" id="diagramCaption">The key clue is whether one atom type is present, different atoms are chemically joined, or different particles are physically mixed.</div></div>`;
 if(type==='compound')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Formula → particle model</div><div class="diagramhelp">Change the formula model and reveal its atom ratio.</div></div><div class="diagramcontrols"><button onclick="formulaMode('H2O')">H₂O</button><button onclick="formulaMode('CO2')">CO₂</button><button onclick="formulaMode('NaCl')">NaCl</button><button onclick="toggleLabels('formula')">Labels</button></div></div><div class="diagramcanvas" id="formulaCanvas">${formulaSVG('H2O')}</div><div class="diagramcaption" id="formulaCaption">H₂O means 2 H : 1 O.</div></div>`;
 if(type==='numberline')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Interactive number line</div><div class="diagramhelp">Change the starting value and watch the jump.</div></div><div class="diagramcontrols"><button onclick="numberMode(-5)">Start −5</button><button onclick="numberMode(3)">Start 3</button><button onclick="numberMode(7)">Start 7</button></div></div><div class="diagramcanvas" id="numberCanvas">${numberSVG(3,-4)}</div><div class="diagramcaption" id="numberCaption">A negative jump moves left; a positive jump moves right.</div></div>`;
 if(type==='force')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Free-body diagram inspector</div><div class="diagramhelp">Compare balanced and unbalanced force diagrams.</div></div><div class="diagramcontrols"><button onclick="forceMode('balanced')">Balanced</button><button onclick="forceMode('unbalanced')">Unbalanced</button><button onclick="toggleLabels('force')">Labels</button></div></div><div class="diagramcanvas" id="forceCanvas">${forceSVG('balanced')}</div><div class="diagramcaption" id="forceCaption">Balanced forces give a zero resultant force; unbalanced forces give a non-zero resultant.</div></div>`;
 if(type==='cell')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Cell explorer</div><div class="diagramhelp">Switch cell type and click organelles to inspect function.</div></div><div class="diagramcontrols"><button onclick="cellMode('animal')">Animal</button><button onclick="cellMode('plant')">Plant</button><button onclick="toggleLabels('cell')">Labels</button></div></div><div class="diagramcanvas" id="cellCanvas">${cellSVG('plant')}</div><div class="diagramcaption" id="cellCaption">Click a structure to connect its structure and function.</div></div>`;
 if(type==='calculus')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Differential calculus visual lab</div><div class="diagramhelp">Move the point along the curve. The tangent gradient updates with the point.</div></div><div class="diagramcontrols"><button onclick="calculusMode(1)">x = 1</button><button onclick="calculusMode(2)">x = 2</button><button onclick="calculusMode(3)">x = 3</button><button onclick="calculusMode(4)">x = 4</button></div></div><div class="diagramcanvas" id="calculusCanvas">${calculusSVG(2)}</div><div class="diagramcaption" id="calculusCaption">For y=x², f′(x)=2x. At x=2 the tangent gradient is 4.</div></div>`;
 if(type==='graph')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Function graph explorer</div><div class="diagramhelp">Switch graph families to compare shape, intercepts and asymptotes.</div></div><div class="diagramcontrols"><button onclick="graphMode('quadratic')">x²</button><button onclick="graphMode('linear')">2x+1</button><button onclick="graphMode('reciprocal')">1/x</button><button onclick="graphMode('exponential')">2ˣ</button></div></div><div class="diagramcanvas" id="graphCanvas">${graphSVG('quadratic')}</div><div class="diagramcaption" id="graphCaption">Start by identifying the shape, intercepts and turning behaviour.</div></div>`;
 if(type==='circuit')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Circuit explorer</div><div class="diagramhelp">Switch between series and parallel layouts and inspect current paths.</div></div><div class="diagramcontrols"><button onclick="circuitMode('series')">Series</button><button onclick="circuitMode('parallel')">Parallel</button></div></div><div class="diagramcanvas" id="circuitCanvas">${circuitSVG('series')}</div><div class="diagramcaption" id="circuitCaption">Series: the same current flows through each component in a single path.</div></div>`;
 if(type==='probability')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Probability model</div><div class="diagramhelp">Choose a representation: Venn diagram, tree or two-way table.</div></div><div class="diagramcontrols"><button onclick="probabilityMode('venn')">Venn</button><button onclick="probabilityMode('tree')">Tree</button><button onclick="probabilityMode('table')">Table</button></div></div><div class="diagramcanvas" id="probabilityCanvas">${probabilitySVG('venn')}</div><div class="diagramcaption" id="probabilityCaption">Use the representation that matches the relationship between the events.</div></div>`;
 if(type==='trig')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Trigonometry visualiser</div><div class="diagramhelp">Move the angle to see the right triangle ratios change.</div></div><div class="diagramcontrols"><button onclick="trigMode(30)">30°</button><button onclick="trigMode(45)">45°</button><button onclick="trigMode(60)">60°</button></div></div><div class="diagramcanvas" id="trigCanvas">${trigSVG(45)}</div><div class="diagramcaption" id="trigCaption">sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse, tan θ = opposite/adjacent.</div></div>`;
 if(type==='genetics')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Inheritance explorer</div><div class="diagramhelp">Change parental alleles and inspect the offspring probabilities.</div></div><div class="diagramcontrols"><button onclick="geneticsMode('Aa','Aa')">Aa × Aa</button><button onclick="geneticsMode('AA','aa')">AA × aa</button><button onclick="geneticsMode('Aa','aa')">Aa × aa</button></div></div><div class="diagramcanvas" id="geneticsCanvas">${geneticsSVG('Aa','Aa')}</div><div class="diagramcaption" id="geneticsCaption">A Punnett square shows possible allele combinations and their probabilities.</div></div>`;
 if(type==='dna')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">DNA → protein story</div><div class="diagramhelp">Step through replication, transcription and translation.</div></div><div class="diagramcontrols"><button onclick="dnaMode(1)">DNA</button><button onclick="dnaMode(2)">Transcription</button><button onclick="dnaMode(3)">Translation</button></div></div><div class="diagramcanvas" id="dnaCanvas">${dnaSVG(1)}</div><div class="diagramcaption" id="dnaCaption">DNA stores the information; transcription produces mRNA; translation uses mRNA to build a protein.</div></div>`;
 if(type==='reaction')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Reaction model</div><div class="diagramhelp">Watch reactants reorganise into products and inspect conservation of atoms.</div></div><div class="diagramcontrols"><button onclick="reactionMode('before')">Reactants</button><button onclick="reactionMode('after')">Products</button><button onclick="reactionMode('balanced')">Balanced view</button></div></div><div class="diagramcanvas" id="reactionCanvas">${reactionSVG('before')}</div><div class="diagramcaption" id="reactionCaption">A chemical equation must conserve the number of each type of atom.</div></div>`;
 if(type==='momentum')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Momentum explorer</div><div class="diagramhelp">Compare how mass and velocity change momentum.</div></div><div class="diagramcontrols"><button onclick="momentumMode(2,3)">2 kg · 3 m/s</button><button onclick="momentumMode(4,3)">4 kg · 3 m/s</button><button onclick="momentumMode(2,6)">2 kg · 6 m/s</button></div></div><div class="diagramcanvas" id="momentumCanvas">${momentumSVG(2,3)}</div><div class="diagramcaption" id="momentumCaption">p = mv. Here p = 6 kg·m·s⁻¹.</div></div>`;
 if(type==='energy')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Mechanical energy explorer</div><div class="diagramhelp">Change the object position and compare gravitational potential and kinetic energy.</div></div><div class="diagramcontrols"><button onclick="energyMode('top')">Top</button><button onclick="energyMode('middle')">Middle</button><button onclick="energyMode('bottom')">Bottom</button></div></div><div class="diagramcanvas" id="energyCanvas">${energySVG('top')}</div><div class="diagramcaption" id="energyCaption">At the top, gravitational potential energy is greatest in this simplified model.</div></div>`;
 if(type==='wave')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">Wave explorer</div><div class="diagramhelp">Change amplitude and wavelength to see what each quantity means.</div></div><div class="diagramcontrols"><button onclick="waveMode(30,90)">Standard</button><button onclick="waveMode(50,90)">Higher amplitude</button><button onclick="waveMode(30,140)">Longer wavelength</button></div></div><div class="diagramcanvas" id="waveCanvas">${waveSVG(30,90)}</div><div class="diagramcaption" id="waveCaption">Amplitude is the maximum displacement from equilibrium; wavelength is the distance between matching points.</div></div>`;
 if(type==='acidbase')return `<div class="diagram"><div class="diagramhead"><div><div class="diagramtitle">pH scale explorer</div><div class="diagramhelp">Select a pH region and connect it to acidity, neutrality or basicity.</div></div><div class="diagramcontrols"><button onclick="acidMode(2)">pH 2</button><button onclick="acidMode(7)">pH 7</button><button onclick="acidMode(12)">pH 12</button></div></div><div class="diagramcanvas" id="acidCanvas">${acidSVG(7)}</div><div class="diagramcaption" id="acidCaption">pH 7 is neutral at ordinary school-level conditions.</div></div>`;
 return ''
}
function calculusSVG(x){const W=680,H=390,x0=55,y0=300,scaleX=58,scaleY=42;let path='';for(let t=-2;t<=5;t+=0.06){const px=x0+(t+2)*scaleX,py=y0-t*t*scaleY;if(py>35&&py<350)path+=(path?'L':'M')+px.toFixed(1)+','+py.toFixed(1)}const px=x0+(x+2)*scaleX,py=y0-x*x*scaleY,m=2*x;const x2=x+1.1,y2=x*x+m*(x2-x);const qx=x0+(x2+2)*scaleX,qy=y0-y2*scaleY;return `<svg viewBox="0 0 ${W} ${H}" aria-label="Derivative tangent graph"><line x1="${x0}" y1="${y0}" x2="640" y2="${y0}" stroke="#777080"/><line x1="${x0+2*scaleX}" y1="30" x2="${x0+2*scaleX}" y2="350" stroke="#777080"/><path d="${path}" fill="none" stroke="#9b7cff" stroke-width="4"/><line x1="${x0+(x+0.8+2)*scaleX}" y1="${y0-(x*x+m*0.8)*scaleY}" x2="${x0+(x-0.8+2)*scaleX}" y2="${y0-(x*x-m*0.8)*scaleY}" stroke="#78c9ff" stroke-width="4"/><circle cx="${px}" cy="${py}" r="9" fill="#fff" stroke="#9b7cff" stroke-width="4"/><text x="54" y="42" fill="#efeaff" font-size="20" font-weight="800">y = x²</text><text x="54" y="70" fill="#bdb6c9" font-size="13">At x=${x}: f′(x)=${m}</text><text x="${Math.min(px+18,560)}" y="${Math.max(py-18,90)}" fill="#cdbfff" font-size="12">tangent gradient = ${m}</text><text x="${px+12}" y="${py+25}" fill="#efeaff" font-size="11">(${x}, ${x*x})</text></svg>`}
function calculusMode(x){$('calculusCanvas').innerHTML=calculusSVG(x);$('calculusCaption').textContent=`For y=x², f′(x)=2x. At x=${x}, the tangent gradient is ${2*x}.`}
function graphSVG(mode){let formula='',color='#9b7cff';if(mode==='quadratic')formula='y=x²';if(mode==='linear')formula='y=2x+1';if(mode==='reciprocal')formula='y=1/x';if(mode==='exponential')formula='y=2ˣ';let pts=[];for(let t=-3;t<=3;t+=0.05){if(mode==='reciprocal'&&Math.abs(t)<0.12)continue;let y=mode==='quadratic'?t*t:mode==='linear'?2*t+1:mode==='reciprocal'?1/t:Math.pow(2,t);if(y<-4||y>8)continue;pts.push([t,y])}const sx=90,sy=45,ox=310,oy=220,xx=t=>ox+t*sx,yy=y=>oy-y*sy;const d=pts.map((p,i)=>(i?'L':'M')+xx(p[0]).toFixed(1)+','+yy(p[1]).toFixed(1)).join('');return `<svg viewBox="0 0 620 330"><line x1="30" y1="220" x2="590" y2="220" stroke="#777080"/><line x1="310" y1="25" x2="310" y2="305" stroke="#777080"/>${mode==='reciprocal'?'<line x1="310" y1="25" x2="310" y2="305" stroke="#ee8ca2" stroke-dasharray="6 7"/>':''}<path d="${d}" fill="none" stroke="${color}" stroke-width="4"/><text x="42" y="48" fill="#efeaff" font-size="20" font-weight="800">${formula}</text><text x="42" y="72" fill="#bdb6c9" font-size="12">Inspect the shape and key graph features.</text></svg>`}
function graphMode(m){$('graphCanvas').innerHTML=graphSVG(m);$('graphCaption').textContent=m==='reciprocal'?'1/x has a vertical asymptote at x=0.':m==='quadratic'?'x² has a turning point at the origin and is symmetric about the y-axis.':m==='linear'?'2x+1 has constant gradient 2 and y-intercept 1.':'2ˣ is always positive and has a horizontal asymptote y=0.'}
function circuitSVG(mode){return `<svg viewBox="0 0 620 300"><path d="M90 150 H170 V90 H450 V150 H530 V230 H90 Z" fill="none" stroke="#d9d3e4" stroke-width="3"/>${mode==='series'?'<circle cx="280" cy="90" r="22" fill="#211b31" stroke="#9b7cff"/><circle cx="360" cy="90" r="22" fill="#211b31" stroke="#9b7cff"/>':'<path d="M270 90 V150 H270 M360 90 V150 H360 M270 90 H350 M270 150 H350" fill="none" stroke="#d9d3e4" stroke-width="3"/><circle cx="270" cy="90" r="20" fill="#211b31" stroke="#9b7cff"/><circle cx="360" cy="90" r="20" fill="#211b31" stroke="#9b7cff"/><circle cx="270" cy="210" r="20" fill="#211b31" stroke="#9b7cff"/><circle cx="360" cy="210" r="20" fill="#211b31" stroke="#9b7cff"/>'}<text x="45" y="48" fill="#efeaff" font-size="20" font-weight="800">${mode==='series'?'Series circuit':'Parallel circuit'}</text><text x="45" y="270" fill="#bdb6c9" font-size="12">Components are represented by simplified circuit symbols for concept learning.</text></svg>`}
function circuitMode(m){$('circuitCanvas').innerHTML=circuitSVG(m);$('circuitCaption').textContent=m==='series'?'Series: one path; current is the same through each series component.':'Parallel: more than one path; current divides among branches.'}
function probabilitySVG(mode){if(mode==='venn')return `<svg viewBox="0 0 620 320"><circle cx="270" cy="165" r="90" fill="#8062e522" stroke="#9b7cff" stroke-width="3"/><circle cx="350" cy="165" r="90" fill="#6ab5ff22" stroke="#78bcff" stroke-width="3"/><text x="225" y="115" fill="#efeaff" font-size="18">A</text><text x="402" y="115" fill="#efeaff" font-size="18">B</text><text x="300" y="165" fill="#fff" font-size="14">A ∩ B</text><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">Venn diagram</text></svg>`;if(mode==='tree')return `<svg viewBox="0 0 620 320"><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">Tree diagram</text><circle cx="90" cy="160" r="8" fill="#fff"/><line x1="98" y1="160" x2="250" y2="95" stroke="#a88cff" stroke-width="3"/><line x1="98" y1="160" x2="250" y2="225" stroke="#7eb8ff" stroke-width="3"/><text x="260" y="100" fill="#ddd7e6" font-size="13">A</text><text x="260" y="230" fill="#ddd7e6" font-size="13">not A</text><line x1="270" y1="95" x2="430" y2="60" stroke="#a88cff" stroke-width="2"/><line x1="270" y1="95" x2="430" y2="130" stroke="#7eb8ff" stroke-width="2"/><line x1="270" y1="225" x2="430" y2="190" stroke="#a88cff" stroke-width="2"/><line x1="270" y1="225" x2="430" y2="260" stroke="#7eb8ff" stroke-width="2"/><text x="45" y="290" fill="#bdb6c9" font-size="12">Multiply along a branch; add mutually exclusive branches.</text></svg>`;return `<svg viewBox="0 0 620 320"><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">Two-way table</text><rect x="120" y="80" width="360" height="170" fill="none" stroke="#8d8797"/><line x1="120" y1="130" x2="480" y2="130" stroke="#8d8797"/><line x1="120" y1="190" x2="480" y2="190" stroke="#8d8797"/><line x1="220" y1="80" x2="220" y2="250" stroke="#8d8797"/><line x1="350" y1="80" x2="350" y2="250" stroke="#8d8797"/><text x="155" y="112" fill="#ddd7e6" font-size="13">Outcome</text><text x="250" y="112" fill="#ddd7e6" font-size="13">B</text><text x="385" y="112" fill="#ddd7e6" font-size="13">not B</text><text x="150" y="165" fill="#ddd7e6" font-size="13">A</text><text x="150" y="225" fill="#ddd7e6" font-size="13">not A</text></svg>`}
function probabilityMode(m){$('probabilityCanvas').innerHTML=probabilitySVG(m);$('probabilityCaption').textContent=m==='venn'?'Use overlap to represent A and B occurring together.':m==='tree'?'Use branches for sequential/dependent outcomes and multiply along branches.':'Use row/column totals to interpret joint and marginal probabilities.'}
function trigSVG(deg){const rad=deg*Math.PI/180,r=105,x0=125,y0=255,x1=x0+r*Math.cos(rad),y1=y0-r*Math.sin(rad);return `<svg viewBox="0 0 620 330"><line x1="90" y1="255" x2="400" y2="255" stroke="#d8d1e2" stroke-width="3"/><line x1="125" y1="255" x2="${x1}" y2="${y1}" stroke="#9b7cff" stroke-width="5"/><line x1="${x1}" y1="${y1}" x2="${x1}" y2="255" stroke="#78bcff" stroke-width="4"/><text x="55" y="50" fill="#efeaff" font-size="20" font-weight="800">θ = ${deg}°</text><text x="55" y="78" fill="#bdb6c9" font-size="12">Visualise opposite, adjacent and hypotenuse.</text><text x="${(x0+x1)/2-20}" y="${(y0+y1)/2-8}" fill="#cdbfff" font-size="12">hyp</text><text x="${(x0+x1)/2}" y="270" fill="#9dd1ff" font-size="12">adj</text><text x="${x1+8}" y="${(y0+y1)/2}" fill="#9dd1ff" font-size="12">opp</text></svg>`}
function trigMode(d){$('trigCanvas').innerHTML=trigSVG(d);$('trigCaption').textContent=`At ${d}°, the triangle shows the opposite, adjacent and hypotenuse used in the trig ratios.`}
function geneticsSVG(a,b){const pa=[a[0],a[1]],pb=[b[0],b[1]],cells=[];for(let i=0;i<2;i++)for(let j=0;j<2;j++)cells.push(pa[i]+pb[j]);return `<svg viewBox="0 0 620 330"><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">${a} × ${b}</text><rect x="170" y="80" width="240" height="200" fill="#10131a" stroke="#8e8798"/><line x1="290" y1="80" x2="290" y2="280" stroke="#8e8798"/><line x1="170" y1="180" x2="410" y2="180" stroke="#8e8798"/><text x="213" y="110" fill="#bdb6c9" font-size="13">${pb[0]}</text><text x="333" y="110" fill="#bdb6c9" font-size="13">${pb[1]}</text><text x="208" y="160" fill="#bdb6c9" font-size="13">${pa[0]}</text><text x="208" y="235" fill="#bdb6c9" font-size="13">${pa[1]}</text><text x="215" y="160" fill="#fff" font-size="18">${cells[0]}</text><text x="335" y="160" fill="#fff" font-size="18">${cells[1]}</text><text x="215" y="235" fill="#fff" font-size="18">${cells[2]}</text><text x="335" y="235" fill="#fff" font-size="18">${cells[3]}</text></svg>`}
function geneticsMode(a,b){$('geneticsCanvas').innerHTML=geneticsSVG(a,b);$('geneticsCaption').textContent=`The four boxes represent the possible allele combinations from ${a} × ${b}.`}
function dnaSVG(step){return `<svg viewBox="0 0 620 320"><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">${step===1?'DNA stores information':step===2?'Transcription → mRNA':'Translation → protein'}</text><path d="M150 75 C240 105 240 215 150 245 M350 75 C260 105 260 215 350 245" stroke="#9b7cff" stroke-width="7" fill="none"/>${Array.from({length:7},(_,i)=>`<line x1="${170+i*25}" y1="${98+i*22}" x2="${330-i*25}" y2="${98+i*22}" stroke="#d9d1e5" stroke-width="3"/>`).join('')}<rect x="410" y="100" width="140" height="110" rx="18" fill="#16131d" stroke="#6f56d7"/><text x="430" y="130" fill="#efeaff" font-size="13">${step===1?'DNA':step===2?'mRNA':'Amino acids'}</text><text x="430" y="158" fill="#bdb6c9" font-size="11">Information is carried</text><text x="430" y="178" fill="#bdb6c9" font-size="11">through the next step.</text></svg>`}
function dnaMode(s){$('dnaCanvas').innerHTML=dnaSVG(s);$('dnaCaption').textContent=s===1?'DNA stores the genetic information.':s===2?'Transcription copies a gene into mRNA.':'Translation uses mRNA codons to assemble a polypeptide.'}
function reactionSVG(mode){return `<svg viewBox="0 0 620 320"><text x="45" y="45" fill="#efeaff" font-size="20" font-weight="800">${mode==='before'?'Before reaction':'After reaction'}</text><g transform="translate(120,120)">${mode==='before'?'<circle cx="0" cy="0" r="26" fill="#9b7cff"/><circle cx="70" cy="0" r="18" fill="#78bcff"/><circle cx="250" cy="0" r="26" fill="#9b7cff"/><circle cx="320" cy="0" r="18" fill="#78bcff"/>':'<g><circle cx="80" cy="0" r="26" fill="#9b7cff"/><circle cx="125" cy="0" r="18" fill="#78bcff"/></g><g><circle cx="300" cy="0" r="26" fill="#9b7cff"/><circle cx="345" cy="0" r="18" fill="#78bcff"/></g>'}</g><text x="55" y="260" fill="#bdb6c9" font-size="12">The atoms are rearranged; they are not created or destroyed.</text></svg>`}
function reactionMode(m){$('reactionCanvas').innerHTML=reactionSVG(m);$('reactionCaption').textContent=m==='balanced'?'A balanced equation has the same number of each atom type on both sides.':m==='before'?'Reactants are present before the chemical change.':'Products are formed after the atoms have been rearranged.'}

function particleSVG(mode){const colors=mode==='element'?'#a88cff':mode==='compound'?'#7eb8ff':'#e7c16a';const other=mode==='mixture'?'#ea839b':colors;let circles='';if(mode==='element'){for(let i=0;i<7;i++)circles+=`<circle cx="${120+i*65}" cy="150" r="22" fill="${colors}"/><circle cx="${120+i*65}" cy="215" r="22" fill="${colors}"/>`}else if(mode==='compound'){for(let i=0;i<5;i++){const x=100+i*100;circles+=`<g class="hotspot" onclick="particleExplain('compound')"><circle cx="${x}" cy="165" r="21" fill="#b08cff"/><circle cx="${x+42}" cy="165" r="17" fill="#7eb8ff"/><line x1="${x+20}" y1="165" x2="${x+24}" y2="165" stroke="#e9e1ff" stroke-width="4"/></g>`}}else{for(let i=0;i<4;i++){circles+=`<circle class="hotspot" onclick="particleExplain('mixture')" cx="${105+i*105}" cy="150" r="22" fill="#b08cff"/><circle class="hotspot" onclick="particleExplain('mixture')" cx="${150+i*88}" cy="215" r="18" fill="#ea839b"/>`}}return `<svg viewBox="0 0 620 340" aria-label="Particle model"><rect x="30" y="30" width="560" height="280" rx="24" fill="#0c0d12" stroke="#34303d"/><text x="52" y="68" fill="#efeaff" font-size="20" font-weight="800">${mode==='element'?'Element':mode==='compound'?'Compound':'Mixture'}</text><g>${circles}</g><g class="diagramLabels"><text x="50" y="295" class="labelchip ${mode==='element'?'':'hiddenlabel'}">one type of atom</text><text x="50" y="295" class="labelchip ${mode==='compound'?'':'hiddenlabel'}">different atoms chemically joined</text><text x="50" y="295" class="labelchip ${mode==='mixture'?'':'hiddenlabel'}">different particles physically mixed</text></g></svg>`}
function formulaSVG(mode){let pairs=mode==='H2O'?['H','H','O']:mode==='CO2'?['C','O','O']:['Na','Cl'];return `<svg viewBox="0 0 620 320"><rect x="30" y="25" width="560" height="270" rx="24" fill="#0c0d12" stroke="#34303d"/><text x="48" y="62" fill="#efeaff" font-size="20" font-weight="800">${mode}</text><g transform="translate(0,35)">${pairs.map((p,i)=>`<g class="hotspot" onclick="formulaExplain('${mode}','${p}')"><circle cx="${240+i*80}" cy="140" r="${p.length>1?27:23}" fill="${p==='O'?'#76a9ff':p==='Cl'?'#e8ba67':'#a98aff'}"/><text x="${232+i*80}" y="146" fill="#fff" font-size="15" font-weight="900">${p}</text></g>`).join('')}</g><text x="54" y="270" class="labelchip">Click a particle • formula ratio: ${mode==='H2O'?'2 H : 1 O':mode==='CO2'?'1 C : 2 O':'1 Na : 1 Cl'}</text></svg>`}
function numberSVG(start,jump){const end=start+jump;let marks='';for(let n=-10;n<=10;n++){const x=40+(n+10)*27;marks+=`<line x1="${x}" y1="145" x2="${x}" y2="165" stroke="#7c7488" stroke-width="1"/><text x="${x-5}" y="190" fill="#bdb6c9" font-size="10">${n}</text>`}const sx=40+(start+10)*27,ex=40+(end+10)*27;return `<svg viewBox="0 0 620 230"><line x1="40" y1="155" x2="580" y2="155" stroke="#eee8fa" stroke-width="2"/>${marks}<circle cx="${sx}" cy="155" r="9" fill="#a88cff"/><line x1="${sx}" y1="105" x2="${ex}" y2="105" stroke="#7eb8ff" stroke-width="3"/><polygon points="${ex},105 ${ex-10},99 ${ex-10},111" fill="#7eb8ff"/><text x="48" y="75" fill="#efeaff" font-size="18" font-weight="800">${start} ${jump>=0?'+':'−'} ${Math.abs(jump)} = ${end}</text></svg>`}
function forceSVG(mode){const right=mode==='unbalanced'?300:250;return `<svg viewBox="0 0 620 340"><rect x="30" y="30" width="560" height="280" rx="24" fill="#0c0d12" stroke="#34303d"/><rect x="245" y="135" width="130" height="72" rx="12" fill="#211b31" stroke="#9b7bff"/><text x="290" y="178" fill="#fff" font-size="16" font-weight="800">box</text><line x1="310" y1="135" x2="310" y2="88" stroke="#7eb8ff" stroke-width="5"/><polygon points="310,80 301,96 319,96" fill="#7eb8ff"/><line x1="310" y1="207" x2="310" y2="255" stroke="#ef849c" stroke-width="5"/><polygon points="310,263 301,247 319,247" fill="#ef849c"/><text x="325" y="92" class="labelchip forceLabel">N</text><text x="325" y="260" class="labelchip forceLabel">W</text>${mode==='unbalanced'?`<line x1="375" y1="171" x2="${right+70}" y2="171" stroke="#7dd2a5" stroke-width="5"/><polygon points="${right+78},171 ${right+62},162 ${right+62},180" fill="#7dd2a5"/><text x="${right+88}" y="176" class="labelchip forceLabel">Fₚᵤₗₗ</text>`:''}<text x="54" y="70" fill="#efeaff" font-size="18" font-weight="800">${mode==='balanced'?'Balanced forces':'Unbalanced forces'}</text></svg>`}
function cellSVG(mode){const plant=mode==='plant';return `<svg viewBox="0 0 620 380"><rect x="40" y="40" width="540" height="300" rx="${plant?40:80}" fill="#11151a" stroke="${plant?'#78b97f':'#9474ff'}" stroke-width="5"/><ellipse cx="310" cy="190" rx="52" ry="40" fill="#6f4fbb" class="hotspot" onclick="cellExplain('nucleus')"/><text x="289" y="196" class="labelchip">Nucleus</text><circle cx="190" cy="125" r="28" fill="#b17b66" class="hotspot" onclick="cellExplain('mitochondrion')"/><circle cx="425" cy="120" r="28" fill="#b17b66" class="hotspot" onclick="cellExplain('mitochondrion')"/>${plant?`<ellipse cx="470" cy="250" rx="34" ry="16" fill="#6fa45e" class="hotspot" onclick="cellExplain('chloroplast')"/><ellipse cx="150" cy="255" rx="34" ry="16" fill="#6fa45e" class="hotspot" onclick="cellExplain('chloroplast')"/><circle cx="310" cy="280" r="42" fill="#526d86" class="hotspot" onclick="cellExplain('vacuole')"/>`:''}<text x="54" y="73" fill="#efeaff" font-size="18" font-weight="800">Typical ${plant?'plant':'animal'} cell</text><text x="55" y="320" class="labelchip">Click a structure to explore its function.</text></svg>`}
function toggleLabels(kind){document.querySelectorAll('.diagramLabels .labelchip').forEach(e=>e.classList.toggle('hiddenlabel'));if(kind==='formula'){const c=$('formulaCaption');if(c)c.textContent+=' • Labels toggled.'}}
function particleMode(m){$('particlesCanvas').innerHTML=particleSVG(m);$('diagramCaption').textContent=m==='element'?'Element: only one type of atom is present.':m==='compound'?'Compound: different atoms are chemically joined in fixed groups.':'Mixture: different particles are together without being chemically joined.'}
function particleExplain(m){$('diagramCaption').textContent=m==='compound'?'Clicked compound group: the atoms are chemically joined, so the group represents a compound particle.':'Clicked particle: different particles are present without being chemically joined, which is a mixture clue.'}
function formulaMode(m){$('formulaCanvas').innerHTML=formulaSVG(m);$('formulaCaption').textContent=m==='H2O'?'H₂O → 2 H : 1 O.':m==='CO2'?'CO₂ → 1 C : 2 O.':'NaCl → 1 Na : 1 Cl.'}
function formulaExplain(m,p){$('formulaCaption').textContent=`${m}: clicked ${p}. The symbol identifies an element; the number/position gives its role in the ratio.`}
function numberMode(start){const jump=start===3?-4:start===7?3:5;$('numberCanvas').innerHTML=numberSVG(start,jump);$('numberCaption').textContent=`Start at ${start}. Adding ${jump} means moving ${jump<0?'left':'right'} on the number line to reach ${start+jump}.`}
function forceMode(m){$('forceCanvas').innerHTML=forceSVG(m);$('forceCaption').textContent=m==='balanced'?'Balanced: resultant force is zero, so acceleration is zero.':'Unbalanced: the resultant force is non-zero, so the object accelerates in the direction of the net force.'}
function cellMode(m){$('cellCanvas').innerHTML=cellSVG(m);$('cellCaption').textContent=`Typical ${m} cell view. Click structures to inspect their exam function.`}
function cellExplain(part){const map={nucleus:'Nucleus: contains DNA/genetic material and helps control cell activities.',mitochondrion:'Mitochondrion: main site of aerobic respiration; high-energy cells may contain many.',chloroplast:'Chloroplast: contains chlorophyll and is the site of photosynthesis.',vacuole:'Large permanent vacuole: contributes to storage and helps maintain turgor in plant cells.'};$('cellCaption').textContent=map[part]||''}


function momentumSVG(m=2,v=3){const p=m*v,w=Math.min(210,45+p*12);return `<svg viewBox="0 0 620 260" role="img" aria-label="Momentum diagram"><defs><marker id="momArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#b9a7ff"/></marker></defs><line x1="55" y1="190" x2="565" y2="190" stroke="#4a4452" stroke-width="3"/><rect x="150" y="125" width="110" height="65" rx="14" fill="#171421" stroke="#8064e8"/><text x="205" y="154" fill="#f5f2fa" text-anchor="middle" font-size="16">${m} kg</text><text x="205" y="176" fill="#aaa1b5" text-anchor="middle" font-size="12">object</text><line x1="265" y1="145" x2="${265+w}" y2="145" stroke="#b9a7ff" stroke-width="6" marker-end="url(#momArrow)"/><text x="405" y="118" fill="#d9d2e5" text-anchor="middle" font-size="14">v = ${v} m/s</text><text x="310" y="45" fill="#fff" font-size="24" font-weight="700">p = mv = ${p} kg·m·s⁻¹</text></svg>`}
function momentumMode(m,v){const c=$('momentumCanvas');if(c)c.innerHTML=momentumSVG(m,v);const t=$('momentumCaption');if(t)t.textContent=`p = mv = ${m} × ${v} = ${m*v} kg·m·s⁻¹. Doubling mass or velocity doubles momentum.`}
function energySVG(mode='top'){const pos={top:[210,50],middle:[310,115],bottom:[430,178]}[mode]||[210,50];return `<svg viewBox="0 0 620 260" role="img" aria-label="Energy conversion diagram"><path d="M90 55 Q310 55 520 190" fill="none" stroke="#4e4758" stroke-width="8" stroke-linecap="round"/><circle cx="${pos[0]}" cy="${pos[1]}" r="20" fill="#9c7cff" stroke="#d7cbff" stroke-width="3"/><line x1="80" y1="210" x2="535" y2="210" stroke="#34303a"/><text x="75" y="42" fill="#b8afc5" font-size="12">higher position → more GPE</text><text x="360" y="240" fill="#b8afc5" font-size="12">lower position → more kinetic energy (idealised)</text></svg>`}
function energyMode(mode){const c=$('energyCanvas');if(c)c.innerHTML=energySVG(mode);const t=$('energyCaption');if(t)t.textContent=mode==='top'?'At the top: gravitational potential energy is high and kinetic energy is low.':mode==='middle'?'In the middle: energy is being transferred from gravitational potential to kinetic.':'At the bottom: kinetic energy is greatest in the idealised friction-free model.'}
function waveSVG(a=30,lambda=90){let d='M 35 130';for(let x=35;x<=585;x+=5){const y=130-a*Math.sin((2*Math.PI*(x-35))/lambda);d+=` L ${x} ${y.toFixed(1)}`;}return `<svg viewBox="0 0 620 260" role="img" aria-label="Wave diagram"><line x1="30" y1="130" x2="590" y2="130" stroke="#3b3642" stroke-dasharray="6 6"/><path d="${d}" fill="none" stroke="#9d7cff" stroke-width="4"/><line x1="75" y1="130" x2="75" y2="${130-a}" stroke="#78cda4" stroke-width="2"/><text x="82" y="${125-a/2}" fill="#9fe4bf" font-size="12">amplitude</text><line x1="125" y1="55" x2="${125+lambda}" y2="55" stroke="#e3c46b" stroke-width="2"/><text x="${125+lambda/2}" y="43" fill="#f0d98e" text-anchor="middle" font-size="12">wavelength</text></svg>`}
function waveMode(a,l){const c=$('waveCanvas');if(c)c.innerHTML=waveSVG(a,l);const t=$('waveCaption');if(t)t.textContent=`Amplitude = ${a} visual units; wavelength = ${l} visual units. Frequency changes inversely with wavelength when wave speed is fixed.`}
function acidSVG(ph=7){const x=50+(ph/14)*520;return `<svg viewBox="0 0 620 220" role="img" aria-label="pH scale"><defs><linearGradient id="phg" x1="0" x2="1"><stop offset="0" stop-color="#d45f73"/><stop offset=".5" stop-color="#e5ca6b"/><stop offset="1" stop-color="#6f9de8"/></linearGradient></defs><rect x="50" y="90" width="520" height="34" rx="17" fill="url(#phg)"/><line x1="${x}" y1="65" x2="${x}" y2="145" stroke="#fff" stroke-width="4"/><circle cx="${x}" cy="65" r="9" fill="#fff"/><text x="${x}" y="45" fill="#fff" text-anchor="middle" font-size="16">pH ${ph}</text><text x="55" y="165" fill="#d9d0dd" font-size="12">acidic</text><text x="310" y="165" fill="#d9d0dd" text-anchor="middle" font-size="12">neutral</text><text x="570" y="165" fill="#d9d0dd" text-anchor="end" font-size="12">basic</text></svg>`}
function acidMode(ph){const c=$('acidCanvas');if(c)c.innerHTML=acidSVG(ph);const t=$('acidCaption');if(t)t.textContent=ph<7?`pH ${ph} is acidic.`:ph===7?'pH 7 is neutral in the standard school-level model.':`pH ${ph} is basic (alkaline).`}

/* =========================
   NOTES RENDERER
   ========================= */
function renderNotes(){const d=S.d;let h='';h+=`<div class="section"><div class="eyebrow">Topic overview</div><h3>${esc(d.name)}</h3><p class="lead">${esc(d.overview)}</p>${S.general?'<div class="callout amber"><b>General material — not curriculum-verified.</b><br>Use this for learning support. Verify the exact examinable scope before relying on it for an exam.</div>':''}</div>`;
h+=`<div class="subjectMethod"><b>${esc((subjectProfiles[S.sub]||{}).label||'Subject learning approach')}</b><p>${esc((subjectProfiles[S.sub]||{}).method||'Learn the ideas, practise accurately and explain your reasoning clearly.')}</p></div>`;h+=`<div class="learningPath"><div class="lp"><span>01</span><b>Understand</b><small>Build the idea in simple language.</small></div><div class="lp"><span>02</span><b>Visualise</b><small>Use the correct diagram, graph or model.</small></div><div class="lp"><span>03</span><b>Practise</b><small>Move from recall to unfamiliar application.</small></div><div class="lp"><span>04</span><b>Exam train</b><small>Use sourced paper questions where available.</small></div></div>`;h+=`<div class="section"><div class="eyebrow">What you must know</div><div class="grid2">${d.scope.map(x=>`<div class="mini"><b>Core requirement</b><p>${esc(x)}</p></div>`).join('')}</div></div>`;
h+=`<div class="section"><div class="eyebrow">Topic coverage</div><p class="subtle">Vic breaks the headline topic into these subtopics so the learner can see what is being covered instead of revising only a title.</p><div class="coverageGrid">${(d.coverage||[]).map((x,i)=>`<div class="coverageItem"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(x)}</b></div>`).join('')}</div>${(d.formulae||[]).length?`<div class="formulaStrip"><b>Key formulae / rules</b><div class="formulaList">${d.formulae.map(f=>`<span>${esc(f)}</span>`).join('')}</div></div>`:''}</div>`;
h+=`<div class="section"><div class="eyebrow">Learning objectives</div><div class="checklist">${d.objectives.map((x,i)=>`<label><input type="checkbox" id="obj${i}"><span>${esc(x)}</span></label>`).join('')}</div></div>`;
h+=`<div class="section"><div class="eyebrow">Prerequisites</div><div>${d.prerequisites.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div>`;
h+=`<div class="section"><div class="eyebrow">Core concepts</div>${d.concepts.map((c,i)=>`<div class="definition"><strong>${i+1}. ${esc(c.t)}</strong><div><b>Simple explanation:</b> ${esc(c.s)}</div><div><b>Exam language:</b> ${esc(c.e)}</div><div><b>Context:</b> ${esc(c.ctx)}</div><div style="margin-top:7px"><b>Examples:</b> ${c.x.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div>`).join('')}</div>`;
h+=coverageDeepDive(d);
h+=diagramHTML(d.diagram?.type)+(d.diagram?.type?diagramTeachingNotes(d.diagram.type):'');
h+=`<div class="section"><div class="eyebrow">Key definitions</div>${d.definitions.map(x=>`<div class="definition"><strong>${esc(x[0])}</strong><div>${esc(x[1])}</div></div>`).join('')}</div>`;
h+=`<div class="section"><div class="eyebrow">Worked examples</div>${d.examples.map((x,i)=>`<div class="example"><h4>Example ${i+1}</h4><p><b>Question:</b> ${esc(x.q)}</p><p><b>Answer:</b> ${esc(x.a)}</p></div>`).join('')}${(d.worked||[]).map(x=>`<div class="example"><h4>${esc(x.title)}</h4>${x.steps.map((s,i)=>`<div class="stepbox"><b>Step ${i+1}</b><span>${esc(s)}</span></div>`).join('')}</div>`).join('')}</div>`;h+=pastPaperSpotlightHTML();
h+=`<div class="section"><div class="eyebrow">Quick checks</div><p class="subtle">Use these while learning. They give immediate feedback without turning the whole lesson into a quiz.</p>${d.quick.map((x,i)=>`<div class="quick"><h4>${esc(x.q)}</h4><div class="quickopts">${x.opts.map((o,j)=>`<button onclick="quickCheck(${i},${j})">${esc(o)}</button>`).join('')}</div><div class="feedback" id="quick${i}"></div></div>`).join('')}</div>`;
h+=`<div class="section"><div class="eyebrow">Common mistakes</div>${d.mistakes.map((x,i)=>`<div class="mistake"><i>${i+1}</i><div>${esc(x)}</div></div>`).join('')}</div>`;
h+=`<div class="section"><div class="eyebrow">Exam focus</div><div class="callout"><b>${esc(d.examFocus)}</b></div><div class="grid2">${d.commandWords.map(x=>`<div class="mini"><b>${esc(x[0])}</b><p>${esc(x[1])}</p></div>`).join('')}</div></div>`;
h+=`<div class="section"><div class="eyebrow">Revision checklist</div><div class="checklist">${d.checklist.map((x,i)=>`<label><input type="checkbox" id="chk${i}"><span>${esc(x)}</span></label>`).join('')}</div></div>`;
$('notes').innerHTML=h;$('sideSummary').innerHTML=`<div class="mini"><b>${(d.coverage||d.concepts||[]).length} covered subtopics</b><p>Visible coverage map so the learner can track what the session teaches.</p></div><div class="mini" style="margin-top:8px"><b>${d.questions.length} practice questions</b><p>Knowledge, understanding, application and exam formats.</p></div><div class="mini" style="margin-top:8px"><b>${d.diagram?'Interactive visual':'Text + worked examples'}</b><p>${d.diagram?'Use the visual to test the concept, not just decorate the lesson.':'This topic is taught through structured explanations and examples.'}</p></div>`;$('sideSource').innerHTML=S.general?'<div class="sourcesmall"><b>Source status</b><br>General learning support — not curriculum-verified.</div>':`<div class="sourcesmall"><b>Curriculum status</b><br>${esc(S.cur)} local mapping.<br><button class="btn ghost small" style="margin-top:8px" onclick="openSources()">View source details</button></div>`}
function quickCheck(i,j){const x=S.d.quick[i],el=$('quick'+i);if(j===x.correct){el.className='feedback show good';el.innerHTML=`<b>Correct.</b> ${esc(x.explain)}`}else{el.className='feedback show bad';el.innerHTML=`<b>Not quite.</b> ${esc(x.explain)}`}}

/* =========================
   PRACTICE ENGINE
   ========================= */
function renderPracticeSummary(){if(!S.d)return;const secs=['Knowledge','Understanding','Application','Exam'];const total=S.d.questions.length;const pp=S.d.questions.filter(q=>q.kind==='pastpaper').length;$('practiceSummary').innerHTML=secs.map(sec=>{const n=S.d.questions.filter(q=>q.sec===sec&&q.kind!=='pastpaper').length;return `<div class="stat"><small>${sec}</small><b>${n}</b><span>questions</span></div>`}).join('')+`<div class="stat"><small>Past papers</small><b>${pp}</b><span>verified-source items</span></div><div class="stat"><small>Total</small><b>${total}</b><span>attempts available</span></div>`}
function renderPractice(){if(!S.d)return;const secs=['All','Knowledge','Understanding','Application','Exam','Past papers'];if(!secs.includes(S.tab))S.tab='All';$('filters').innerHTML=secs.map(x=>`<button class="${S.tab===x?'active':''}" data-filter="${x}">${x}</button>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{saveAnswers();S.tab=b.dataset.filter;renderPractice()});let qs=S.d.questions;if(S.tab==='Past papers')qs=qs.filter(q=>q.kind==='pastpaper');else if(S.tab!=='All')qs=qs.filter(q=>q.sec===S.tab&&q.kind!=='pastpaper');$('practice').innerHTML=qs.map(renderQuestion).join('');bindQuestionInputs();updateAttemptProgress();if(S.results.length)paintResults()}
function renderQuestion(q){const source=sourceLabel(q);let body='';if(q.type==='short')body=`<textarea id="a${q.id}" placeholder="Write your answer…">${esc(S.answers[q.id]||'')}</textarea>`;else if(q.type==='mcq')body=`<div class="answeroptions">${q.options.map((o,i)=>`<label class="answeroption"><input type="radio" name="q${q.id}" value="${i}" ${S.answers[q.id]===i?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div>`;else if(q.type==='numeric')body=`<input id="a${q.id}" type="text" inputmode="decimal" placeholder="Enter your numerical answer…" value="${esc(S.answers[q.id]||'')}"><div class="hint">Include a unit where the question requires one.</div>`;else if(q.type==='tf')body=`<div class="answeroptions"><label class="answeroption"><input type="radio" name="q${q.id}" value="true" ${S.answers[q.id]===true?'checked':''}><span>True</span></label><label class="answeroption"><input type="radio" name="q${q.id}" value="false" ${S.answers[q.id]===false?'checked':''}><span>False</span></label></div>`;const support=q.kind==='pastpaper'?`<div class="examSupport">${q.diagram?`<div class="qDiagram">${ppDiagramSVG(q.diagram)}</div>`:''}<div class="guidebar"><button type="button" onclick="toggleGuide('qh-${q.id}')">Hint</button><button type="button" onclick="toggleGuide('qs-${q.id}')">Show steps</button><button type="button" onclick="toggleGuide('qm-${q.id}')">Memo</button></div><div class="guidedBox" id="qh-${q.id}"><h5>Hint</h5><p>${esc((q.hints||[])[0]||'Identify the principle and the information given.')}</p></div><div class="guidedBox" id="qs-${q.id}"><h5>Step-by-step solution</h5><div class="stepReveal">${(q.solutionSteps||[]).map((x,i)=>`<div class="stepLine"><b>Step ${i+1}</b><br>${esc(x)}</div>`).join('')}</div></div><div class="guidedBox" id="qm-${q.id}"><h5>Memo / expected answer</h5><p>${esc(q.expected)}</p><p><b>Exam tip:</b> ${esc(q.examNote||q.fix||'Show all required working.')}</p></div></div>`:'';return `<div class="q ${q.kind==='pastpaper'?'pastpaper':''}"><div class="qhead"><div><div class="qmeta"><span class="qtag">${q.kind==='pastpaper'?'Past paper':esc(q.sec)}</span><span class="qtag">${q.m} marks</span><span class="qtag">${q.type==='mcq'?'Multiple choice':q.type==='tf'?'True / false':q.type==='numeric'?'Numerical':'Written response'}</span></div><h4>${esc(q.prompt)}</h4></div></div>${support}${body}<div class="qsource ${q.kind==='pastpaper'?'sourceVerified':''}">${esc(source)}${q.kind==='pastpaper'&&q.sourceMeta?.url?` · <a href="${esc(q.sourceMeta.url)}" target="_blank" rel="noopener" style="color:#cdbdff">official source ↗</a>`:''}</div><div class="qresult" id="m${q.id}"></div></div>`}
function bindQuestionInputs(){S.d.questions.forEach(q=>{if(q.type==='short'||q.type==='numeric'){const el=$('a'+q.id);if(el)el.oninput=()=>{S.answers[q.id]=el.value;updateAttemptProgress()}}else{document.querySelectorAll(`[name="q${q.id}"]`).forEach(el=>el.onchange=()=>{S.answers[q.id]=q.type==='mcq'?Number(el.value):el.value==='true';updateAttemptProgress()})}})}
function saveAnswers(){if(!S.d)return;S.d.questions.forEach(q=>{if(q.type==='short'||q.type==='numeric'){const el=$('a'+q.id);if(el)S.answers[q.id]=el.value}else{const chosen=document.querySelector(`[name="q${q.id}"]:checked`);if(chosen)S.answers[q.id]=q.type==='mcq'?Number(chosen.value):chosen.value==='true'}})}
function updateAttemptProgress(){if(!S.d)return;const answered=S.d.questions.filter(q=>{const a=S.answers[q.id];return a!==undefined&&String(a).trim()!==''}).length;const pct=Math.round(answered/S.d.questions.length*100);$('attemptProgress').textContent=`${answered} / ${S.d.questions.length} answered`;$('practiceProgress').style.width=pct+'%'}
function evaluate(q,a){if(q.type==='mcq'){const ok=Number(a)===q.correct;return{status:ok?'Correct':'Incorrect',score:ok?1:0,missing:ok?[]:[q.prompt],why:ok?q.explain:'The selected option does not match the required concept.',fix:q.explain||'Select the option that matches the concept.'}}
if(q.type==='tf'){const val=a===true||a==='true';const ok=val===q.answer;return{status:ok?'Correct':'Incorrect',score:ok?1:0,missing:ok?[]:['correct judgement'],why:q.explain,fix:q.explain}}
if(q.type==='numeric'){const clean=s=>normalizeText(s).replace(/[^0-9.\-]/g,'');const ok=Math.abs(parseFloat(clean(a))-parseFloat(clean(q.answer)))<0.0001;return{status:ok?'Correct':'Incorrect',score:ok?1:0,missing:ok?[]:['correct numerical result'],why:ok?q.explain:'Your numerical result does not match the expected result.',fix:q.explain}}
if(!String(a||'').trim())return{status:'Incorrect',score:0,missing:q.criteria.map(c=>c.concept),why:'No answer was submitted.',fix:q.fix};let matched=q.criteria.filter(c=>criterionHit(a,c.terms));let ratio=q.criteria.length?matched.length/q.criteria.length:0;return{status:ratio>=0.8?'Correct':ratio>0?'Partially correct':'Incorrect',score:ratio,missing:q.criteria.filter(c=>!criterionHit(a,c.terms)).map(c=>c.concept),why:ratio>=0.8?'Your response covers the required knowledge points sufficiently.':'Some required knowledge points are missing, unclear or unsupported.',fix:q.fix||'Add the missing knowledge points and rewrite your answer clearly.'}
}
function submitPractice(){if(!S.d)return;saveAnswers();S.results=S.d.questions.map(q=>{const a=S.answers[q.id]??'';return{q,a,...evaluate(q,a)}});persistDistinctionAttempt();stopExamMode(false);nav('reportView')}
function paintResults(){S.results.filter(r=>S.tab==='All'||(S.tab==='Past papers'?r.q.kind==='pastpaper':(r.q.sec===S.tab&&r.q.kind!=='pastpaper'))).forEach(r=>{const el=$('m'+r.q.id);if(!el)return;const cls=r.status==='Correct'?'correct':r.status==='Partially correct'?'partial':'incorrect';el.className='qresult show';el.innerHTML=`<div class="result"><div class="resultstatus ${cls}">${r.status} · ${Math.round(r.score*100)}% of this question</div><div class="resultgrid"><div class="mini"><b>Your answer</b><p>${esc(String(r.a??'')||'No answer')}</p></div><div class="mini"><b>Expected answer</b><p>${esc(r.q.expected)}</p></div><div class="mini"><b>Why</b><p>${esc(r.why||r.q.explain||'Compare your response with the expected concept.')}</p></div><div class="mini"><b>Missing concept</b><p>${esc(r.missing.join(', ')||'None identified')}</p></div></div><div class="callout exactfix"><b>Exact fix:</b> ${esc(r.fix||'Review the expected answer and rewrite it.')}</div></div>`})}

