function buildReport(){
 if(!S.d||!S.results.length){$('report').innerHTML=`<div class="card reportbox"><h3>No report yet</h3><p>Complete the practice set first. Your report will diagnose knowledge, understanding, application, exam technique and past-paper readiness.</p><button class="btn primary" onclick="nav('practiceView')">Go to practice</button></div>`;return}
 const r=S.results,earned=r.reduce((n,x)=>n+x.q.m*x.score,0),total=r.reduce((n,x)=>n+x.q.m,0)||1,pct=Math.round(earned/total*100);
 const cats={Knowledge:[0,0],Understanding:[0,0],Application:[0,0],Exam:[0,0]};r.forEach(x=>{cats[x.q.sec][0]+=x.q.m*x.score;cats[x.q.sec][1]+=x.q.m});
 const catPct=Object.fromEntries(Object.entries(cats).map(([k,v])=>[k,v[1]?Math.round(v[0]/v[1]*100):0]));
 const pp=r.filter(x=>x.q.kind==='pastpaper'),ppEarned=pp.reduce((n,x)=>n+x.q.m*x.score,0),ppTotal=pp.reduce((n,x)=>n+x.q.m,0),ppPct=ppTotal?Math.round(ppEarned/ppTotal*100):null;
 const critical=r.filter(x=>x.status!=='Correct'),weak=Object.entries(catPct).filter(([,v])=>v<70).map(([k])=>k),strong=Object.entries(catPct).filter(([,v])=>v>=80).map(([k])=>k);const ready=pct>=80&&weak.length===0&&critical.length<=Math.max(2,Math.floor(r.length*.2));
 const subtopicIssues=[...new Set(critical.flatMap(x=>x.missing).filter(Boolean))].slice(0,6);let plan=[];subtopicIssues.slice(0,4).forEach(c=>plan.push(`Review and teach aloud: ${c}.`));critical.slice(0,4).forEach(x=>plan.push(`Redo ${x.q.id.toUpperCase()} without the memo, then compare every step with the worked solution.`));if((catPct.Application||0)<75)plan.push('Complete at least three new application questions before retaking the set.');if((catPct.Exam||0)<75)plan.push('Do two timed exam-style questions with full working, command-word discipline and units.');if(ppTotal&&ppPct<70)plan.push('Repeat the sourced past-paper questions without hints until you can reproduce the method independently.');plan.push(ready?'Progress to the next topic or a harder sourced paper set.':'Retake the topic after the targeted fixes.');
 const summary=ready?'You are showing secure topic control across recall, explanation, application and exam response.':pct>=60?`You have usable understanding, but the report shows specific gaps${weak.length?' in '+weak.join(', '):''}. Fix these before moving on.`:'The foundations are not secure enough yet. Relearn the weak subtopics, work through the visual/steps, then retake.';
 $('report').innerHTML=`<div class="reporthero"><div class="card scorebox ${ready?'ready':'notready'}"><div class="score">${pct}%</div><small>overall mastery</small><div class="subtle" style="margin-top:8px">${earned.toFixed(1)} / ${total} marks</div></div><div class="card summary"><div class="eyebrow">Learner summary</div><h2>${ready?'Ready to progress':'Targeted improvement needed'}</h2><p>${esc(summary)}</p><div class="mastergrid">${Object.entries(catPct).map(([k,v])=>`<div class="mitem"><b>${esc(k)}</b><div class="bar"><i style="width:${v}%"></i></div><small>${v}%</small></div>`).join('')}</div></div></div>
 <div class="ppSummary"><div class="card reportbox"><div class="eyebrow">Past-paper readiness</div><div class="readiness">${ppPct===null?'—':ppPct+'%'}</div><p>${ppTotal?`${pp.length} sourced question${pp.length===1?'':'s'} attempted · ${ppEarned.toFixed(1)} / ${ppTotal} marks`:'No sourced paper items were available for this topic in the local bank.'}</p></div><div class="card reportbox"><h3>Strong areas</h3><p>${strong.length?esc(strong.join(' · ')):'No domain is securely mastered yet.'}</p></div><div class="card reportbox"><h3>Priority weaknesses</h3><p>${subtopicIssues.length?esc(subtopicIssues.join(' · ')):'No major knowledge-point weakness identified.'}</p></div></div>
 <div class="card reportbox" style="margin-top:12px"><h3>Detailed diagnosis</h3>${critical.length?critical.map(x=>`<div class="missed"><b>${esc(x.q.id.toUpperCase())} · ${esc(x.status)}${x.q.kind==='pastpaper'?' · PAST PAPER':''}</b><p><b>Your answer:</b> ${esc(String(x.a)||'No answer')}</p><p><b>Correct answer:</b> ${esc(x.q.expected)}</p><p><b>Why:</b> ${esc(x.why)}</p><p><b>Missing concept:</b> ${esc(x.missing.join(', ')||'None identified')}</p>${x.q.solutionSteps?`<div class="callout"><b>Correct method:</b><ol>${x.q.solutionSteps.map(st=>`<li>${esc(st)}</li>`).join('')}</ol></div>`:''}<div class="callout amber"><b>Exact fix:</b><br>${esc(x.fix)}</div></div>`).join(''):'<div class="callout green"><b>No incorrect or partially correct responses.</b><br>Move to a harder application set and keep your exam technique sharp.</div>'}</div>
 <div class="card reportbox" style="margin-top:12px"><h3>Exact improvement plan</h3><ol class="plan">${plan.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="statusbanner ${ready?'ready':'notready'}"><b>${ready?'READY TO PROGRESS':'NOT READY YET'}</b><div class="subtle" style="margin-top:4px">${ready?'Move on, then revisit this topic with a mixed past-paper set later.':'Complete the targeted fixes, then retake without hints.'}</div></div></div>
 <div class="reportgrid"><div class="card reportbox"><h3>Question coverage</h3><div class="milestone">${Object.entries(cats).map(([k,v])=>`<div class="mini"><b>${esc(k)}</b><p>${Math.round(v[0]*10)/10} / ${v[1]} marks earned</p></div>`).join('')}</div></div><div class="card reportbox"><h3>Exam behaviour</h3><p>${ppTotal?`Past-paper score: ${ppPct}%. ${ppPct>=80?'You are transferring the topic into authentic exam conditions well.':'Use the step-by-step solutions as a method checklist, then redo the same questions without support.'}`:'Build toward sourced-paper practice once a verified paper item is available for this topic.'}</p></div></div>`
}

