function openSources(){if(!S.d)return;const sourceMeta={authority:'South African curriculum reference layer',document:S.cur==='South Africa • CAPS'?'DBE CAPS-aligned local mapping':'IEB-aligned study catalogue (detailed assessment scope should be verified)',verified:S.general?'No — general material':'Local topic mapping present'};const papers=S.d.pastPapers||[];$('modalBody').innerHTML=`<div class="eyebrow">Curriculum & sources</div><h2>${esc(S.d.name)}</h2>${S.general?'<div class="callout amber"><b>General material.</b><br>This page is deliberately not presented as curriculum-verified.</div>':''}<div class="definition"><strong>Curriculum</strong><div>${esc(S.cur)}</div></div><div class="definition"><strong>Grade / subject</strong><div>${esc(S.grade)} · ${esc(S.sub)}</div></div><div class="definition"><strong>Mapping status</strong><div>${esc(sourceMeta.verified)}</div></div><div class="definition"><strong>Source discipline</strong><div>Vic separates curriculum scope, generated teaching content and authenticated examination sources. A question is only labelled Past paper when official DBE source metadata is attached. Adapted or reconstructed wording is labelled explicitly.</div></div>${papers.length?`<h3 style="margin-top:18px">Past-paper sources used</h3><div class="sourceList">${papers.map(q=>`<div class="sourceItem"><b>${esc(q.sourceMeta.year)} ${esc(q.sourceMeta.exam)} · ${esc(q.sourceMeta.paper)} · Q${esc(q.sourceMeta.question)}</b><div>${esc(q.sourceMeta.status)}<br><a href="${esc(q.sourceMeta.url)}" target="_blank" rel="noopener">Open official DBE source ↗</a></div></div>`).join('')}</div>`:'<div class="callout"><b>No verified past-paper item is embedded for this topic yet.</b><br>The normal practice questions remain clearly labelled as exam-style practice.</div>'}`;$('modal').classList.add('open')}
function downloadNotes(){if(!S.d)return;const d=S.d;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(d.name)} · Vic Study Notes</title><style>body{font-family:Arial,sans-serif;color:#17131c;max-width:860px;margin:0 auto;padding:35px;line-height:1.65}h1{font-size:38px;margin:0 0 5px}h2{margin-top:30px;color:#4a3980}.meta{color:#6d6674;font-size:12px}.box{border:1px solid #dcd6e4;border-radius:12px;padding:14px 16px;margin:10px 0;break-inside:avoid}.call{padding:12px 14px;background:#f6f2ff;border-left:3px solid #7558dc;border-radius:0 10px 10px 0}li{margin:5px 0}@media print{body{padding:0 10mm}}</style></head><body><h1>${esc(d.name)}</h1><div class="meta">Grade ${esc(S.grade)} · ${esc(S.cur)} · ${esc(S.sub)}${S.general?' · GENERAL MATERIAL — NOT CURRICULUM-VERIFIED':''}</div><h2>Learning objectives</h2><ul>${d.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Topic overview</h2><p>${esc(d.overview)}</p><h2>What you must know</h2><ul>${d.scope.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Topic coverage</h2><ol>${(d.coverage||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${(d.formulae||[]).length?`<h2>Key formulae / rules</h2><div class="call">${d.formulae.map(x=>esc(x)).join('<br>')}</div>`:''}<h2>Core concepts</h2>${d.concepts.map(c=>`<div class="box"><h3>${esc(c.t)}</h3><p><b>Simple explanation:</b> ${esc(c.s)}</p><p><b>Exam language:</b> ${esc(c.e)}</p><p><b>Context:</b> ${esc(c.ctx)}</p><p><b>Examples:</b> ${c.x.map(x=>esc(x)).join(' • ')}</p></div>`).join('')}<h2>Key definitions</h2><ul>${d.definitions.map(x=>`<li><b>${esc(x[0])}:</b> ${esc(x[1])}</li>`).join('')}</ul><h2>Worked examples</h2>${d.examples.map(x=>`<div class="box"><b>${esc(x.q)}</b><p>${esc(x.a)}</p></div>`).join('')}${(d.worked||[]).map(x=>`<div class="box"><b>${esc(x.title)}</b><ol>${x.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`).join('')}<h2>Exam focus</h2><div class="call">${esc(d.examFocus)}</div><ul>${d.commandWords.map(x=>`<li><b>${esc(x[0])}:</b> ${esc(x[1])}</li>`).join('')}</ul><h2>Common mistakes</h2><ul>${d.mistakes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Revision checklist</h2><ul>${d.checklist.map(x=>`<li>☐ ${esc(x)}</li>`).join('')}</ul>
</body></html>`;const b=new Blob([html],{type:'text/html'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`Vic-${d.name.replace(/[^a-z0-9]+/gi,'-')}-Study-Notes.html`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800)}


/* =========================
   DISTINCTION HUB / DESKTOP
   ========================= */
const DX_KEY='vicDistinctionDesktop.v1';
const SESSION_KEY='vicDistinctionDesktop.session.v1';
let DX_MEMORY=null,SESSION_MEMORY=null;
let dxFocusTimer=null,dxFocusRemaining=25*60,dxFocusRunning=false,dxExamTimer=null,dxExamRemaining=0,dxExamActive=false,dxFlashIndex=0;
function dxDefault(){return{settings:{target:80,dailyMinutes:60,focusMinutes:25,examDate:''},attempts:[],mistakes:[],activity:{},focusSessions:0}}
function dxLoad(){try{const raw=localStorage.getItem(DX_KEY)||DX_MEMORY||'null',x=JSON.parse(raw);return x&&typeof x==='object'?Object.assign(dxDefault(),x,{settings:Object.assign(dxDefault().settings,x.settings||{})}):dxDefault()}catch(e){try{const x=JSON.parse(DX_MEMORY||'null');return x&&typeof x==='object'?Object.assign(dxDefault(),x,{settings:Object.assign(dxDefault().settings,x.settings||{})}):dxDefault()}catch(_){return dxDefault()}}}
function dxSave(d){const raw=JSON.stringify(d);DX_MEMORY=raw;try{localStorage.setItem(DX_KEY,raw)}catch(e){}}
function saveSession(){const raw=JSON.stringify({grade:S.grade,cur:S.cur,sub:S.sub,topic:S.topic,topicMode:S.topicMode||'browse'});SESSION_MEMORY=raw;try{localStorage.setItem(SESSION_KEY,raw)}catch(e){}}
function loadSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||SESSION_MEMORY||'null')}catch(e){try{return JSON.parse(SESSION_MEMORY||'null')}catch(_){return null}}}
function dxLocalDate(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function dxToday(){return dxLocalDate()}
function dxDateAdd(days){const d=new Date();d.setDate(d.getDate()+days);return dxLocalDate(d)}
function dxPercent(n){return Math.max(0,Math.min(100,Math.round(n||0)))}
function dxAttemptPct(results){const total=results.reduce((n,x)=>n+(x.q.m||1),0)||1;return Math.round(results.reduce((n,x)=>n+(x.q.m||1)*x.score,0)/total*100)}
function dxCategories(results){const bag={Knowledge:[0,0],Understanding:[0,0],Application:[0,0],Exam:[0,0]};results.forEach(x=>{if(!bag[x.q.sec])bag[x.q.sec]=[0,0];bag[x.q.sec][0]+=(x.q.m||1)*x.score;bag[x.q.sec][1]+=(x.q.m||1)});return Object.fromEntries(Object.entries(bag).map(([k,v])=>[k,v[1]?Math.round(v[0]/v[1]*100):0]))}
function persistDistinctionAttempt(){if(!S.d||!S.results.length)return;const d=dxLoad(),pct=dxAttemptPct(S.results),today=dxToday();const a={id:Date.now(),date:new Date().toISOString(),grade:S.grade,curriculum:S.cur,subject:S.sub,topic:S.topic||S.d.name,pct,categories:dxCategories(S.results),questions:S.results.length};d.attempts.push(a);d.attempts=d.attempts.slice(-250);d.activity[today]=d.activity[today]||{questions:0,minutes:0,sessions:0};d.activity[today].questions+=S.results.length;d.activity[today].sessions+=1;
 const seen=new Set();S.results.forEach(r=>{const key=[S.grade,S.sub,S.topic||S.d.name,r.q.id].join('|');seen.add(key);const idx=d.mistakes.findIndex(m=>m.key===key);if(r.status==='Correct'){if(idx>=0){d.mistakes[idx].repetitions=(d.mistakes[idx].repetitions||0)+1;d.mistakes[idx].lastScore=1;d.mistakes[idx].due=dxDateAdd(d.mistakes[idx].repetitions>=2?14:7);d.mistakes[idx].mastered=d.mistakes[idx].repetitions>=2}}else{const item={key,grade:S.grade,subject:S.sub,topic:S.topic||S.d.name,qid:r.q.id,prompt:r.q.prompt,expected:r.q.expected,answer:String(r.a??''),missing:r.missing||[],lastSeen:today,lastScore:r.score,repetitions:0,due:dxDateAdd(1),mastered:false};if(idx>=0)d.mistakes[idx]=Object.assign(d.mistakes[idx],item);else d.mistakes.push(item)}});d.mistakes=d.mistakes.slice(-300);dxSave(d)}
function dxStreak(d){let n=0,x=new Date();for(let i=0;i<365;i++){const k=x.toISOString().slice(0,10);if(d.activity[k]&&(d.activity[k].questions||d.activity[k].minutes)){n++;x.setDate(x.getDate()-1)}else if(i===0){x.setDate(x.getDate()-1)}else break}return n}
function dxRecentAverage(d){const a=d.attempts.slice(-8);return a.length?Math.round(a.reduce((n,x)=>n+x.pct,0)/a.length):0}
function dxReadiness(d){const avg=dxRecentAverage(d),target=d.settings.target||80,due=d.mistakes.filter(m=>!m.mastered&&m.due<=dxToday()).length,streak=dxStreak(d);let score=avg*.72+Math.min(streak,7)/7*15+Math.max(0,13-Math.min(due,13));if(!d.attempts.length)score=0;return dxPercent(score)}
function dxMasteryRows(d){const map={};d.attempts.forEach(a=>{const k=a.subject+' · '+a.topic;map[k]=map[k]||[];map[k].push(a.pct)});return Object.entries(map).map(([k,v])=>[k,Math.round(v.slice(-3).reduce((n,x)=>n+x,0)/Math.min(v.length,3))]).sort((a,b)=>a[1]-b[1])}
function dxPlan(d){const due=d.mistakes.filter(m=>!m.mastered&&m.due<=dxToday());const mastery=dxMasteryRows(d);const plan=[];if(due.length)plan.push(['Review mistakes',`Clear ${Math.min(due.length,8)} due mistake-card${due.length===1?'':'s'} before new work.`]);if(mastery.length&&mastery[0][1]<(d.settings.target||80))plan.push(['Repair weakest topic',`${mastery[0][0]} is currently around ${mastery[0][1]}%. Relearn the weak subtopics, then do application questions.`]);if(S.d)plan.push(['Current topic',`Complete a focused ${S.topic||S.d.name} practice block and explain each missed answer aloud.`]);else plan.push(['Choose one priority topic','Pick the topic most likely to cost marks in your next test and build a full study session.']);plan.push(['Exam technique','Finish with one timed Exam/Past-paper block without hints, then correct it immediately.']);return plan.slice(0,4)}
function dxWeek(d){const out=[];const now=new Date();for(let i=6;i>=0;i--){const x=new Date(now);x.setDate(now.getDate()-i);const k=x.toISOString().slice(0,10),v=d.activity[k]||{questions:0,minutes:0,sessions:0};out.push({k,label:x.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2),value:(v.questions||0)+Math.round((v.minutes||0)/5),questions:v.questions||0,minutes:v.minutes||0})}return out}
function dxDaysToExam(d){if(!d.settings.examDate)return null;const t=new Date(d.settings.examDate+'T12:00:00'),n=new Date();return Math.max(0,Math.ceil((t-n)/(86400000)))}
function renderDistinctionHub(){const root=$('dxDashboard');if(!root)return;const d=dxLoad(),avg=dxRecentAverage(d),ready=dxReadiness(d),streak=dxStreak(d),due=d.mistakes.filter(m=>!m.mastered&&m.due<=dxToday()),mastery=dxMasteryRows(d),week=dxWeek(d),max=Math.max(1,...week.map(x=>x.value)),days=dxDaysToExam(d);$('dxTargetBadge').textContent=(d.settings.target||80)+'%';const plan=dxPlan(d);const flash=S.d?.definitions||[];if(dxFlashIndex>=flash.length)dxFlashIndex=0;
 root.innerHTML=`<div class="dxGrid">
 <div class="card dxCard wide"><div class="eyebrow">Distinction dashboard</div><div class="dxKpis"><div class="dxKpi"><small>Recent average</small><b>${avg||'—'}${avg?'%':''}</b><span>Last ${Math.min(d.attempts.length,8)} attempts</span></div><div class="dxKpi"><small>Study streak</small><b>${streak}</b><span>active day${streak===1?'':'s'}</span></div><div class="dxKpi"><small>Due reviews</small><b>${due.length}</b><span>mistakes ready to revisit</span></div><div class="dxKpi"><small>${days===null?'Practice attempts':'Days to exam'}</small><b>${days===null?d.attempts.length:days}</b><span>${days===null?'saved locally':'use them deliberately'}</span></div></div></div>
 <div class="card dxCard"><div class="eyebrow">A-readiness</div><div class="dxReadiness"><div class="dxRing" style="--p:${ready}"><b>${ready}%</b></div><div class="dxMeta"><div class="line"><span>Target</span><b>${d.settings.target}%</b></div><div class="dxBar"><i style="width:${Math.min(100,(avg/(d.settings.target||80))*100)}%"></i></div><div class="line"><span>Recent performance</span><b>${avg||0}%</b></div><div class="line"><span>Open weak points</span><b>${d.mistakes.filter(m=>!m.mastered).length}</b></div></div></div><p style="margin-top:12px">This is a study-readiness indicator, not a predicted school mark. It rewards performance, consistency and closing mistakes.</p></div>
 <div class="card dxCard wide"><div class="eyebrow">Today's distinction plan</div><h3>Do the highest-value work first</h3><div class="dxPlan">${plan.map((x,i)=>`<div class="dxTask"><i>${i+1}</i><div><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div></div>`).join('')}</div><div class="dxActions"><button class="btn primary" onclick="dxStartPriority()">Start priority topic</button><button class="btn secondary" onclick="startExamMode()">Start timed exam mode</button></div></div>
 <div class="card dxCard"><div class="eyebrow">Focus sprint</div><div class="dxTimer"><div class="dxClock" id="dxClock">${dxFmt(dxFocusRemaining)}</div><div class="dxTimerLabel" id="dxTimerLabel">Deep work · distractions off</div></div><div class="dxActions" style="justify-content:center"><button class="btn primary small" onclick="dxToggleFocus()" id="dxFocusBtn">${dxFocusRunning?'Pause':'Start'}</button><button class="btn ghost small" onclick="dxResetFocus()">Reset</button></div></div>
 <div class="card dxCard half"><div class="eyebrow">7-day consistency</div><h3>Questions + focused minutes</h3><div class="dxActivity">${week.map(x=>`<div class="dxDay"><div class="bar" title="${x.questions} questions · ${x.minutes} min"><i style="height:${Math.max(4,Math.round(x.value/max*100))}%"></i></div><small>${x.label}</small></div>`).join('')}</div></div>
 <div class="card dxCard half"><div class="eyebrow">Mastery map</div><h3>Weakest topics rise to the top</h3><div class="dxMastery">${mastery.length?mastery.slice(0,7).map(x=>`<div class="dxMasteryRow"><b title="${esc(x[0])}">${esc(x[0])}</b><div class="dxBar"><i style="width:${x[1]}%"></i></div><span>${x[1]}%</span></div>`).join(''):'<div class="dxEmpty">Complete a practice set and your topic mastery map will start building automatically.</div>'}</div></div>
 <div class="card dxCard half"><div class="eyebrow">Smart review queue</div><h3>Mistakes return before you forget them</h3><div class="dxList">${due.length?due.slice(0,8).map(m=>dxMistakeHTML(m)).join(''):'<div class="dxEmpty">Nothing is due right now. Incorrect and partially correct answers will automatically enter this queue.</div>'}</div></div>
 <div class="card dxCard half"><div class="eyebrow">Mistake book</div><h3>Your marks are hiding here</h3><div class="dxList">${d.mistakes.filter(m=>!m.mastered).slice(-8).reverse().map(m=>dxMistakeHTML(m,true)).join('')||'<div class="dxEmpty">Your mistake book is empty. Once you practise, Vic will collect recurring gaps here instead of letting them disappear after the report.</div>'}</div></div>
 <div class="card dxCard half"><div class="eyebrow">Active recall</div><h3>Definition flashcards</h3>${flash.length?`<div class="dxFlash" id="dxFlash" onclick="this.classList.toggle('reveal')"><small>Tap to reveal</small><b>${esc(flash[dxFlashIndex][0])}</b><p>${esc(flash[dxFlashIndex][1])}</p></div><div class="dxActions"><button class="btn ghost small" onclick="dxNextFlash(-1)">Previous</button><button class="btn secondary small" onclick="dxNextFlash(1)">Next card</button></div>`:'<div class="dxEmpty">Build a study session first. Vic will turn that topic’s key definitions into quick active-recall cards.</div>'}</div>
 <div class="card dxCard half"><div class="eyebrow">Formula / exam vault</div><h3>${S.d?esc(S.topic||S.d.name):'Current topic tools'}</h3>${S.d&&((S.d.formulae||[]).length||(S.d.checklist||[]).length)?`<div class="dxList">${(S.d.formulae||[]).slice(0,8).map(f=>`<div class="dxItem"><span class="dxChip">Formula / rule</span><p>${esc(f)}</p></div>`).join('')}${(S.d.checklist||[]).slice(0,5).map(c=>`<div class="dxItem"><span class="dxChip">Exam check</span><p>${esc(c)}</p></div>`).join('')}</div>`:'<div class="dxEmpty">Choose a topic and Vic will collect its key rules, formulae and exam checklist here.</div>'}</div>
 <div class="card dxCard full"><div class="eyebrow">Personal study settings</div><h3>Make the system work toward your actual target</h3><div class="dxSettings"><label>Target percentage<input id="dxTarget" type="number" min="50" max="100" value="${d.settings.target}"></label><label>Daily study minutes<input id="dxDaily" type="number" min="15" max="360" value="${d.settings.dailyMinutes}"></label><label>Focus sprint minutes<input id="dxFocus" type="number" min="10" max="90" value="${d.settings.focusMinutes}"></label><label>Next major exam<input id="dxExamDate" type="date" value="${d.settings.examDate||''}"></label></div><div class="dxActions"><button class="btn primary" onclick="dxSaveSettings()">Save settings</button><button class="btn secondary" onclick="dxExportProgress()">Export progress</button><button class="btn secondary" onclick="dxChooseImport()">Import progress</button><button class="btn ghost" onclick="dxClearData()">Reset local progress</button></div></div>
 </div>`}
function dxMistakeHTML(m,book=false){return `<div class="dxItem"><div class="dxItemTop"><div><span class="dxChip">${esc(m.subject)}</span> <span class="dxChip">${esc(m.topic)}</span></div><span class="${m.due<=dxToday()?'dxDue':'subtle'}">${m.due<=dxToday()?'Due now':'Review '+esc(m.due)}</span></div><p><b>${esc(m.prompt)}</b></p>${m.missing?.length?`<p>Missing: ${esc(m.missing.join(', '))}</p>`:''}<div class="dxActions"><button class="btn secondary small" onclick="dxRevealMistake('${encodeURIComponent(m.key)}',this)">Show correction</button><button class="btn ghost small" onclick="dxMarkReviewed('${encodeURIComponent(m.key)}')">${book?'Mark mastered':'Reviewed'}</button></div></div>`}
function dxRevealMistake(encoded,btn){const key=decodeURIComponent(encoded),d=dxLoad(),m=d.mistakes.find(x=>x.key===key);if(!m)return;const box=document.createElement('div');box.className='callout';box.style.marginTop='9px';box.innerHTML=`<b>Expected answer</b><br>${esc(m.expected)}${m.answer?`<br><br><b>Your previous answer</b><br>${esc(m.answer)}`:''}`;btn.closest('.dxItem').appendChild(box);btn.remove()}
function dxMarkReviewed(encoded){const key=decodeURIComponent(encoded),d=dxLoad(),m=d.mistakes.find(x=>x.key===key);if(!m)return;m.repetitions=(m.repetitions||0)+1;m.due=dxDateAdd(m.repetitions===1?3:m.repetitions===2?7:21);if(m.repetitions>=3)m.mastered=true;dxSave(d);renderDistinctionHub()}
function dxSaveSettings(){const d=dxLoad();d.settings.target=Math.max(50,Math.min(100,Number($('dxTarget').value)||80));d.settings.dailyMinutes=Math.max(15,Number($('dxDaily').value)||60);d.settings.focusMinutes=Math.max(10,Number($('dxFocus').value)||25);d.settings.examDate=$('dxExamDate').value||'';dxSave(d);dxFocusRemaining=d.settings.focusMinutes*60;renderDistinctionHub()}
function dxFmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function dxToggleFocus(){if(dxFocusRunning){clearInterval(dxFocusTimer);dxFocusRunning=false;if($('dxFocusBtn'))$('dxFocusBtn').textContent='Resume';return}if(dxFocusRemaining<=0)dxResetFocus();dxFocusRunning=true;if($('dxFocusBtn'))$('dxFocusBtn').textContent='Pause';dxFocusTimer=setInterval(()=>{dxFocusRemaining--;if($('dxClock'))$('dxClock').textContent=dxFmt(dxFocusRemaining);if(dxFocusRemaining<=0){clearInterval(dxFocusTimer);dxFocusRunning=false;const d=dxLoad(),today=dxToday(),mins=d.settings.focusMinutes||25;d.focusSessions=(d.focusSessions||0)+1;d.activity[today]=d.activity[today]||{questions:0,minutes:0,sessions:0};d.activity[today].minutes=(d.activity[today].minutes||0)+mins;dxSave(d);if($('dxTimerLabel'))$('dxTimerLabel').textContent='Sprint complete — take a short reset.';if($('dxFocusBtn'))$('dxFocusBtn').textContent='Start again'}},1000)}
function dxResetFocus(){clearInterval(dxFocusTimer);dxFocusRunning=false;dxFocusRemaining=(dxLoad().settings.focusMinutes||25)*60;if($('dxClock'))$('dxClock').textContent=dxFmt(dxFocusRemaining);if($('dxFocusBtn'))$('dxFocusBtn').textContent='Start'}
function dxNextFlash(dir){const n=S.d?.definitions?.length||0;if(!n)return;dxFlashIndex=(dxFlashIndex+dir+n)%n;renderDistinctionHub()}
function dxStartPriority(){const d=dxLoad(),mastery=dxMasteryRows(d);if(mastery.length){const raw=mastery[0][0],parts=raw.split(' · '),topic=parts.slice(1).join(' · ');if(topic){nav('setupView');S.sub=parts[0];S.topic=topic;$('topic').value=topic;populateSetup();updateNotice();return}}nav('setupView')}
function startExamMode(){if(!S.d){nav('setupView');alert('Choose and build a topic first. Then Distinction Mode can create a timed exam block from it.');return}dxExamActive=true;dxExamRemaining=45*60;document.body.classList.add('examMode');S.tab='Exam';nav('practiceView');dxRenderExamBar();clearInterval(dxExamTimer);dxExamTimer=setInterval(()=>{dxExamRemaining--;dxRenderExamBar();if(dxExamRemaining<=0){clearInterval(dxExamTimer);submitPractice()}},1000)}
function dxRenderExamBar(){const bar=$('examModeBar');if(!bar)return;if(!dxExamActive){bar.classList.remove('show');bar.innerHTML='';return}bar.classList.add('show');bar.innerHTML=`<strong>Timed exam mode · hints and worked solutions hidden</strong><div><span>${dxFmt(dxExamRemaining)}</span> <button class="btn ghost small" onclick="stopExamMode(true)">Exit</button></div>`}
function stopExamMode(manual=true){clearInterval(dxExamTimer);dxExamActive=false;document.body.classList.remove('examMode');dxRenderExamBar();if(manual&&S.view==='practiceView')renderPractice()}
function dxExportProgress(){const d=dxLoad(),payload={exported:new Date().toISOString(),settings:d.settings,attempts:d.attempts,mistakes:d.mistakes,activity:d.activity};const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Vic-Distinction-Progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function dxChooseImport(){const el=$('dxImportFile');if(el){el.value='';el.click()}}
function dxImportProgress(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x||typeof x!=='object'||!Array.isArray(x.attempts)||!Array.isArray(x.mistakes)||typeof x.activity!=='object')throw new Error('Invalid backup');const d=dxDefault();d.settings=Object.assign(d.settings,x.settings||{});d.attempts=x.attempts.slice(-250);d.mistakes=x.mistakes.slice(-300);d.activity=x.activity||{};d.focusSessions=Number(x.focusSessions||0);dxSave(d);dxFocusRemaining=(d.settings.focusMinutes||25)*60;renderDistinctionHub();alert('Progress imported successfully.')}catch(e){alert('That file is not a valid Vic Distinction progress backup.')}};r.readAsText(file)}
function dxClearData(){if(!confirm('Reset all locally saved Vic Distinction progress on this computer? This cannot be undone.'))return;try{localStorage.removeItem(DX_KEY)}catch(e){}DX_MEMORY=null;dxResetFocus();renderDistinctionHub()}
const _dxRenderPractice=renderPractice;renderPractice=function(){_dxRenderPractice();dxRenderExamBar()};



